def compute(vars):
    balance_2017 = vars["v1"]
    balance_2018 = vars["v2"]
    change = balance_2018 - balance_2017

    return {
        "value": change,
        "trace": {
            "balance_2017": balance_2017,
            "balance_2018": balance_2018,
            "change": change,
            "output_meta": {
                "currency": "USD",
                "scale": "thousand",
                "unit": None
            }
        }
    }
